    "json_mode": true,
    "temperature": 0.7
  },
  "brand": {
    "name": "REPLACE: название",
    "about": "REPLACE: чем занимаетесь, для кого, чем отличаетесь — фактами",
    "audience": "REPLACE: кто читает и что им важно",
    "voice": "по-человечески, конкретно, без канцелярита и восклицательных знаков",
    "rules": [
      "Обращение на «вы»",
      "Без хэштегов, если канал их не требует",
      "Эмодзи — не больше двух на пост"
    ],
    "cta": "REPLACE: что предлагаем сделать читателю — подписаться, записаться, написать в личку"
  },
  "pillars": [
    {
      "name": "Польза",
