    },
    {
      "name": "Разбор",
      "description": "типичная ошибка или миф и как правильно"
    },
    {
      "name": "Изнутри",
      "description": "как мы работаем, процесс, команда, решения"
    },
    {
      "name": "Предложение",
      "description": "услуга или продукт через задачу клиента, не чаще раза в неделю"
    }
  ],
