  const all = values || [];
  const header = all.length > 0 && String(all[0][0]).trim().toLowerCase() === 'id';
  return { header, rows: (header ? all.slice(1) : all).map((r, i) => ({ sheetRow: i + (header ? 2 : 1), post: planObject(r) })) };
}
