  const content = input && input.choices && input.choices[0] && input.choices[0].message && input.choices[0].message.content;
  if (!content) return { problem: input && input.error ? 'llm_error' : 'no_answer' };
  try { const t = String(content).replace(/```(json)?/g, ''); return { data: JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)) }; } catch (e) { return { problem: 'bad_json' }; }
}
