}
slots.sort((a, b) => a.at - b.at);
if (!slots.length) return [{ json: { plan: false, slots: [], has_header: table.header } }];
const recent = table.rows.map(({ post }) => post.topic).filter(Boolean).slice(-(cfg.ideas_lookback || 40));
const pillars = (cfg.pillars || []).map((p) => `- ${p.name}: ${p.description}`).join('\n');
