    '- Не повторяй недавние темы.',
    '- brief — 1–3 предложения: о чём пост, какой главный тезис, что читатель должен сделать после.',
    'Ответь только JSON: {"ideas": [{"topic": "...", "brief": "...", "pillar": "..."}]}',
  ].join('\n') },
  { role: 'user', content: JSON.stringify({ slots: slots.map((s) => ({ when: s.publish_at, channel: s.channel, pillar: s.pillar })), recent_topics: recent }) },
]) } }];

